import{_ as o,o as d,c as a,ag as c}from"./chunks/framework.DyxC4IQh.js";const u=JSON.parse('{"title":"方向键光标","description":"用 WASD 或 HJKL 把光标按屏幕坐标走到元素上再点，判定只比中心点，以及哪些元素该走标签。","frontmatter":{"description":"用 WASD 或 HJKL 把光标按屏幕坐标走到元素上再点，判定只比中心点，以及哪些元素该走标签。"},"headers":[],"relativePath":"guide/cursor.md","filePath":"guide/cursor.md","lastUpdated":1793279156000}'),t={name:"guide/cursor.md"};function i(r,e,p,n,h,s){return d(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="方向键光标" tabindex="-1">方向键光标 <a class="header-anchor" href="#方向键光标" aria-label="Permalink to &quot;方向键光标&quot;">​</a></h1><p>标签够用。目标密集成一片时，你要找的那一个往往要两个字母，眼睛得把满屏标签扫一遍；想把屏幕一排排看下去，逐个找标签同样麻烦。这两种情况下用方向键，把光标走到框上再点。</p><h2 id="怎么用" tabindex="-1">怎么用 <a class="header-anchor" href="#怎么用" aria-label="Permalink to &quot;怎么用&quot;">​</a></h2><p>按 <code>W</code> <code>A</code> <code>S</code> <code>D</code> 或 <code>H</code> <code>J</code> <code>K</code> <code>L</code>。屏幕上还没有光标时，方向键从屏幕中心起算：第一次按下，光标锚在中心那个方向上离你最近的可点击元素，周围画一圈绿框（半透明填充）。</p><p>此后按方向键在元素之间走，按点击键（hint 模式内固定 <code>Space</code>；模式外用设置里的光标点击键，默认 <code>Space</code>，候选与撞行规则见<a href="/vimact-site/guide/settings.html">应用设置</a>）点它。hint 模式外按 <code>Esc</code> 清除光标；hint 模式内 <code>Esc</code> 退出的是 hint 模式，光标留在原地。</p><p>光标不依赖 hint 模式。不开 <code>F</code>，光靠方向键加一个点击键也能用完整套导航。</p><h2 id="走位按屏幕几何-不按控件树" tabindex="-1">走位按屏幕几何，不按控件树 <a class="header-anchor" href="#走位按屏幕几何-不按控件树" aria-label="Permalink to &quot;走位按屏幕几何，不按控件树&quot;">​</a></h2><p>一次按键一次选择：按下去的时候，屏幕上现成的候选表被扫一遍，取那个方向上中心离你最近的一个。没有预先算好的邻接表，也没有层级栈，界面滚动或改版都不需要重建什么。</p><p>判据只有中心点。目标元素的中心落在你要的那一侧（按 <code>L</code> 就是中心横坐标更大），它才参加比较；打分时主轴上隔多远照算，另一条轴上的偏移按两倍计。正对着你的邻居胜过斜上方的邻居，连着按 <code>J</code> 时落点尽量留在同一列。框跟框重不重叠、谁包住谁，都不参与判定：一个占满屏宽的整行和行尾一颗开关，在这套算法里只是两个中心点。</p><p>分数完全相同时，落点是候选表里排在前面那一个。候选表按阅读顺序排（先上后下、先左后右），并列就是左上优先。</p><p>8 像素一行的容差只用在贴标签的阅读顺序上，走位没有容差。</p><h2 id="走位实际走出来的样子" tabindex="-1">走位实际走出来的样子 <a class="header-anchor" href="#走位实际走出来的样子" aria-label="Permalink to &quot;走位实际走出来的样子&quot;">​</a></h2><p>设置页每一行整行可点，行尾一个开关。光标停在行上按 <code>L</code>：整行占满屏宽，行右边没有别的东西，开关的中心在行中心右侧，一按就拿到开关。再按 <code>L</code> 原地不动，按 <code>H</code> 落回整行。往下走分两种：站在行上按 <code>J</code>，落点是下一整行，两行的中心在同一列上，侧向偏移 0 赢过开关那点横距；站在开关上按 <code>J</code>，落点是下一行的开关。</p><p>同一套几何有两处跟直觉对不上，碰上这种情况直接点标签：</p><ul><li>中心跟容器重合的元素走不进去。卡片正中央一颗播放按钮，它的中心就是卡片的中心，任何方向键都算不出它落在哪一侧。</li><li>分数只认中心距离，不认谁包着谁。一排卡片每张带左右两颗按钮时，从卡片中心按 <code>L</code> 拿到的可能不是这张卡片的右按钮，而是上方工具条里偏右的那颗芯片：芯片横偏 50 像素、纵偏 220，卡片自己的按钮横偏 370、纵偏 70，折算下来芯片的分数还低 20。</li></ul><p>列表尽头同理：最后一行按 <code>J</code>，下面没有中心更低的候选，光标停在原地。</p><p>这些判断都不需要预先知道谁是容器：光标只问一句，这个方向上离我中心最近的是谁。</p><h2 id="什么时候消失" tabindex="-1">什么时候消失 <a class="header-anchor" href="#什么时候消失" aria-label="Permalink to &quot;什么时候消失&quot;">​</a></h2><p>光标有 4 秒不活动超时。最后一次移动之后 4 秒内没有新操作，光标自动清除；这条判定在 hint 模式显示标签期间不执行，标签还挂着的时候，光标不会因为手停下来而被收走。超时检查跟着界面刷新走，约每 32 毫秒一次。这段时间里屏幕内容变了，光标会跟着重新锚定到节点当前位置；同名内容（列表项回收复用）进出屏幕时，光标按屏幕位置挂回同一行，不跟着复用的字串串行。节点消失、不可见、或尺寸归零，光标立即清除。</p><p>刷新循环只在 hint 模式或光标存在时运行，退出 hint 模式时它被整个摘掉。所以在 hint 模式里走出光标、再按 <code>Esc</code> 退出，绿框会留在屏幕上：不走超时，也不跟随界面移动，直到你再按一次方向键把它接回去。</p><p>再按 <code>F</code> 进 hint 模式时，光标先被清掉。</p><h2 id="关掉一组方向键" tabindex="-1">关掉一组方向键 <a class="header-anchor" href="#关掉一组方向键" aria-label="Permalink to &quot;关掉一组方向键&quot;">​</a></h2><p>WASD 和 HJKL 各自可以独立关闭，见<a href="/vimact-site/guide/settings.html">应用设置</a>。关掉的那组，四个字母就还给标签字符集，屏幕上的标签会更短。</p><p>保留跟着开关走：WASD 开着，<code>w</code> <code>a</code> <code>s</code> <code>d</code> 就当方向键，标签里不会出现这四个字母；把 WASD 关掉，它们立刻还给标签，哪怕 HJKL 还开着。HJKL 同理。</p>',24)])])}const _=o(t,[["render",i]]);export{u as __pageData,_ as default};
